# emit KEY: print a project file (from the source tree, or embedded in the built single-file installer)
emit() {
  if [[ ${TERMFX_DIST:-0} == 1 ]]; then
    local fn="__emb_${1//[^A-Za-z0-9]/_}"; "$fn"
  else
    cat -- "$ROOT/$1"
  fi
}
put() { # KEY DEST [MODE]
  mkdir -p "$(dirname "$2")"; emit "$1" > "$2"; chmod "${3:-644}" "$2"
}

# ---- lib/ui.sh ----
# lib/ui.sh - colors, logging helpers, banner (sourced by install.sh)
# ------------------------------------------------------------------ ui helpers
if [[ -t 1 && -z ${NO_COLOR:-} ]]; then
  C0=$'\e[0m'; CB=$'\e[1m'; CD=$'\e[2m'
  CR=$'\e[38;5;204m'; CG=$'\e[38;5;114m'; CY=$'\e[38;5;221m'; CC=$'\e[38;5;117m'; CM=$'\e[38;5;183m'
else
  C0=""; CB=""; CD=""; CR=""; CG=""; CY=""; CC=""; CM=""
fi
STEP_N=0; STEP_T=9
step() { STEP_N=$((STEP_N + 1)); printf '\n%s[%d/%d]%s %s%s%s\n' "$CM" "$STEP_N" "$STEP_T" "$C0" "$CB" "$*" "$C0"; }
# Long messages wrap at the terminal width (continuation lines indented) instead of breaking mid-word.
_tw() { local c=${COLUMNS:-0}; ((c > 0)) || c=$(tput cols 2>/dev/null || echo 80); [[ $c =~ ^[0-9]+$ ]] || c=80; ((c >= 40)) || c=40; printf '%s' "$c"; }
_msg() { # colour glyph text...
  local col=$1 g=$2; shift 2
  local w; w=$(( $(_tw) - 4 ))
  local first=1 line
  while IFS= read -r line; do
    if ((first)); then printf '  %s%s%s %s\n' "$col" "$g" "$C0" "$line"; first=0
    else printf '    %s\n' "$line"; fi
  done < <(printf '%s\n' "$*" | fold -s -w "$w" 2>/dev/null || printf '%s\n' "$*")
}
info() { _msg "$CC" "•" "$*"; }
ok()   { _msg "$CG" "✔" "$*"; }
warn() { _msg "$CY" "!" "$*" >&2; }
err()  { _msg "$CR" "✘" "$*" >&2; }
die()  { err "$*"; exit 1; }
have() { command -v "$1" >/dev/null 2>&1; }
have_tty() { { : </dev/tty; } 2>/dev/null; }

banner() {
  printf '%s' "$CM"
  cat <<'EOF'
  ╔╦╗╔═╗╦═╗╔╦╗╔═╗═╗ ╦
   ║ ║╣ ╠╦╝║║║╠╣ ╔╩╦╝
   ╩ ╚═╝╩╚═╩ ╩╚  ╩ ╚═
EOF
  printf '%s  animated terminal header + pro shell UI  v%s%s\n' "$CD" "$VERSION" "$C0"
}

usage() {
  cat <<EOF
termfx installer v$VERSION

USAGE
  $0 [install|uninstall|restore|doctor] [options]

OPTIONS
  -y, --yes             non-interactive (accept defaults)
  --art FILE            use FILE as your ASCII art (any size, multi-frame ok)
  --art-url URL         download ASCII art from URL
  --art-name NAME       name for the imported art (default: custom)
  --paste               paste ASCII art interactively (finish with Ctrl-D)
  --effect NAME         choose any effect (see the complete catalog after install or run termfx effect list)
  --palette NAME        choose any palette or use "#hex,#hex,..." (complete catalogue after install)
  --fetch-preset NAME   fastfetch panel preset (classic compact minimal clean full gamer server developer aesthetic hybridfetch ultra; default: classic)
  --starship-theme NAME choose a named Starship theme (termfx starship theme list)
  --shell zsh|bash|both|auto   which shell(s) to integrate (default: auto)
  --no-packages         do not install anything (no sudo, no downloads)
  --no-font             skip the Nerd Font
  --font                force font install even with --no-packages
  --no-terminal         do not touch Ghostty / kitty config
  --keep-old            do NOT reset my old terminal customizations (default: back them
                        up to ~/.termfx-backup and start from clean defaults)
  --reset               force a fresh backup even if termfx is already installed
  --keep-fetch          do not disable existing fastfetch/neofetch lines in rc
  --force               overwrite built-in art / config with fresh defaults
  --purge               (uninstall) also delete your config and art
  -h, --help            this help

AFTER INSTALL
  termfx --help         customise art, effects, themes
  termfx doctor         diagnose a missing header / tools
  termfx restore        put your old terminal setup back
EOF
}

# ---- lib/packages.sh ----
# lib/packages.sh - distro detection, package install, user-space fallbacks, font
# =============================================================================
DISTRO_ID=unknown; DISTRO_LIKE=""; DISTRO_NAME="Linux"; PM=""; SUDO=""; NO_PRIV=0

detect_system() {
  if [[ -r /etc/os-release ]]; then
    eval "$(. /etc/os-release; printf 'DISTRO_ID=%q DISTRO_LIKE=%q DISTRO_NAME=%q' "${ID:-unknown}" "${ID_LIKE:-}" "${PRETTY_NAME:-Linux}")"
  fi
  for pm in pacman apt-get dnf yum zypper apk xbps-install emerge brew; do
    if have "$pm"; then PM=${pm%-get}; PM=${PM%-install}; break; fi
  done
  if ((EUID == 0)); then SUDO=""
  elif have sudo; then SUDO="sudo"
  elif have doas; then SUDO="doas"
  else NO_PRIV=1; fi
  if [[ $PM == brew ]]; then SUDO=""; NO_PRIV=0; fi
  return 0
}

pkg_name() { # logical name -> package name for $PM  (empty = not available)
  local l=$1
  case $PM:$l in
    apt:python|dnf:python|yum:python|zypper:python|apk:python|xbps:python) echo python3 ;;
    emerge:python) echo dev-lang/python ;;
    *:python) echo python ;;
    emerge:curl) echo net-misc/curl ;;
    emerge:fastfetch) echo app-misc/fastfetch ;;
    emerge:eza) echo sys-apps/eza ;;
    emerge:bat) echo sys-apps/bat ;;
    emerge:fzf) echo app-shells/fzf ;;
    emerge:fontconfig) echo media-libs/fontconfig ;;
    emerge:git) echo dev-vcs/git ;;
    emerge:unzip) echo app-arch/unzip ;;
    emerge:xz) echo app-arch/xz-utils ;;
    pacman:font) echo ttf-jetbrains-mono-nerd ;;
    apk:font) echo font-jetbrains-mono-nerd ;;
    brew:font) echo "font-jetbrains-mono-nerd-font" ;;
    *:font) echo "" ;;
    *) echo "$l" ;;
  esac
}

pm_refresh() {
  case $PM in
    apt) $SUDO apt-get update -qq || true ;;
    zypper) $SUDO zypper -n refresh >/dev/null 2>&1 || true ;;
    apk) $SUDO apk update >/dev/null 2>&1 || true ;;
    xbps) $SUDO xbps-install -S -y >/dev/null 2>&1 || true ;;
    dnf|yum) true ;;
  esac
}

pm_install() { # one package at a time so a missing one never aborts the rest
  local p=$1
  case $PM in
    pacman) $SUDO pacman -S --needed --noconfirm "$p" ;;
    apt)    $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y "$p" ;;
    dnf|yum) $SUDO "$PM" install -y "$p" ;;
    zypper) $SUDO zypper -n install --no-recommends "$p" ;;
    apk)    $SUDO apk add "$p" ;;
    xbps)   $SUDO xbps-install -y "$p" ;;
    emerge) $SUDO emerge --noreplace --quiet "$p" ;;
    brew)   if [[ $p == font-* ]]; then brew install --cask "$p"; else brew install "$p"; fi ;;   # fonts are casks
    *)      return 1 ;;
  esac
}

try_pkg() { # logical-name
  local p; p=$(pkg_name "$1")
  [[ -n $p ]] || return 1
  info "installing ${CB}$p${C0} via $PM"
  if pm_install "$p" >/dev/null 2>&1; then ok "$p"; return 0; fi
  warn "$p is not available via $PM"; return 1
}

fetch() { # url dest
  local url=$1 out=$2
  if have curl; then curl -fsSL --retry 3 --connect-timeout 15 -o "$out" "$url"
  elif have wget; then wget -q -O "$out" "$url"
  elif have python3; then python3 -c 'import sys,urllib.request as u; u.urlretrieve(sys.argv[1], sys.argv[2])' "$url" "$out"
  else return 1; fi
}

font_has_v3_glyphs() {
  have fc-list && have fc-query && have python3 || return 1
  fc-list 2>/dev/null | grep -qi 'JetBrainsMono.*Nerd\|JetBrainsMonoNL\? Nerd' || return 1
  local font_file charset
  font_file=$(fc-match -f '%{file}' 'JetBrainsMono Nerd Font' 2>/dev/null) || return 1
  [[ -r $font_file ]] || return 1
  charset=$(fc-query -f '%{charset}' "$font_file" 2>/dev/null) || return 1
  python3 - "$charset" <<'PY'
import sys
try:
    ranges = []
    for item in sys.argv[1].split():
        ends = item.split("-", 1)
        ranges.append((int(ends[0], 16), int(ends[-1], 16)))
    # U+F01C5 is a current Material Design Nerd Font glyph. Its presence
    # distinguishes Nerd Fonts v3+ from fonts that lost MDI glyphs in v3.
    raise SystemExit(0 if any(lo <= 0xF01C5 <= hi for lo, hi in ranges) else 1)
except (ValueError, IndexError):
    raise SystemExit(1)
PY
}

gh_arch() { # echoes tag per tool
  local m; m=$(uname -m)
  case $1:$m in
    fastfetch:x86_64) echo amd64 ;;
    fastfetch:aarch64|fastfetch:arm64) echo aarch64 ;;
    fastfetch:armv7l) echo armv7l ;;
    fastfetch:riscv64) echo riscv64 ;;
    fastfetch:ppc64le) echo ppc64le ;;
    eza:x86_64)
      if have ldd && ldd --version 2>&1 | grep -qi musl; then echo x86_64-unknown-linux-musl
      else echo x86_64-unknown-linux-gnu; fi ;;
    eza:aarch64|eza:arm64)
      if have ldd && ldd --version 2>&1 | grep -qi musl; then echo aarch64-unknown-linux-musl
      else echo aarch64-unknown-linux-gnu; fi ;;
    eza:armv7l) echo arm-unknown-linux-gnueabihf ;;
    *) echo "" ;;
  esac
}

fallback_fastfetch() {
  local a; a=$(gh_arch fastfetch); [[ -n $a ]] || return 1
  local tmp; tmp=$(mktemp -d)
  fetch "https://github.com/fastfetch-cli/fastfetch/releases/latest/download/fastfetch-linux-$a.tar.gz" "$tmp/f.tgz" \
    && tar -xzf "$tmp/f.tgz" -C "$tmp" || { rm -rf "$tmp"; return 1; }
  local b; b=$(find "$tmp" -type f -name fastfetch | head -n1)
  [[ -n $b ]] && install -m755 "$b" "$BIN_DIR/fastfetch"
  rm -rf "$tmp"; [[ -x $BIN_DIR/fastfetch ]]
}
fallback_starship() {
  local tmp; tmp=$(mktemp)
  fetch "https://starship.rs/install.sh" "$tmp" && sh "$tmp" -y -b "$BIN_DIR" >/dev/null 2>&1
  local rc=$?; rm -f "$tmp"; return $rc
}
fallback_eza() {
  local a; a=$(gh_arch eza); [[ -n $a ]] || return 1
  local tmp; tmp=$(mktemp -d)
  fetch "https://github.com/eza-community/eza/releases/latest/download/eza_$a.tar.gz" "$tmp/e.tgz" \
    && tar -xzf "$tmp/e.tgz" -C "$tmp" || { rm -rf "$tmp"; return 1; }
  local b; b=$(find "$tmp" -type f -name eza | head -n1)
  [[ -n $b ]] && install -m755 "$b" "$BIN_DIR/eza"
  rm -rf "$tmp"; [[ -x $BIN_DIR/eza ]]
}
fallback_fzf() {
  have git || return 1
  [[ -d $HOME/.fzf ]] || git clone -q --depth 1 https://github.com/junegunn/fzf.git "$HOME/.fzf" || return 1
  "$HOME/.fzf/install" --bin >/dev/null 2>&1 || return 1
  ln -sf "$HOME/.fzf/bin/fzf" "$BIN_DIR/fzf"
}

ensure_tool() { # command logical [fallback-fn]
  local cmd=$1 logical=$2 fb=${3:-}
  have "$cmd" && { ok "$cmd already installed"; return 0; }
  [[ -x $BIN_DIR/$cmd ]] && { ok "$cmd (user install)"; return 0; }
  if [[ -n $PM && $NO_PRIV == 0 ]]; then try_pkg "$logical" && have "$cmd" && return 0; fi
  if [[ -n $fb ]]; then
    info "trying user-space install of $cmd"
    if "$fb"; then ok "$cmd installed to $BIN_DIR"; return 0; fi
  fi
  warn "$cmd not installed - termfx will fall back gracefully"
  return 1
}

install_packages() {
  detect_system
  info "system: ${CB}$DISTRO_NAME${C0} (id=$DISTRO_ID${DISTRO_LIKE:+, like=$DISTRO_LIKE})  package manager: ${CB}${PM:-none}${C0}"
  [[ $(uname -s) == Linux ]] || warn "non-Linux system detected - best effort only"
  if [[ -n $PM && $NO_PRIV == 1 ]]; then warn "no root/sudo/doas: system packages skipped, using user-space installs"; fi
  if [[ -n $PM && $NO_PRIV == 0 && -n $SUDO ]]; then info "sudo may ask for your password"; $SUDO -v 2>/dev/null || true; fi
  [[ -n $PM && $NO_PRIV == 0 ]] && pm_refresh
  mkdir -p "$BIN_DIR"
  ensure_tool python3 python || die "python3 is required"
  have curl || have wget || ensure_tool curl curl || true
  ensure_tool fastfetch fastfetch fallback_fastfetch || true
  ensure_tool starship starship fallback_starship || true
  ensure_tool eza eza fallback_eza || true
  if ! have bat && ! have batcat; then ensure_tool bat bat || true; fi
  have bat || { have batcat && ln -sf "$(command -v batcat)" "$BIN_DIR/bat"; } || true
  ensure_tool fzf fzf fallback_fzf || true
  have fc-cache || ensure_tool fc-cache fontconfig || true
}

install_font() {
  if font_has_v3_glyphs; then ok "JetBrainsMono Nerd Font v3+ with current icon glyphs already present"; return 0; fi
  if [[ $DO_FONT == auto ]] && { [[ -n ${SSH_CONNECTION:-} ]] || [[ -z ${DISPLAY:-}${WAYLAND_DISPLAY:-} && ${XDG_SESSION_TYPE:-tty} != wayland && ${XDG_SESSION_TYPE:-tty} != x11 ]]; }; then
    info "headless/SSH session: skipping the font (install it on the machine that shows the terminal, or use --font)"; return 0
  fi
  if [[ ${DO_PKGS:-1} == 1 && -n $PM && $NO_PRIV == 0 && -n $(pkg_name font) ]]; then
    try_pkg font && font_has_v3_glyphs && { ok "Nerd Font v3+ icon glyphs verified"; return 0; }
  fi
  info "downloading JetBrainsMono Nerd Font (user fonts)"
  local tmp; tmp=$(mktemp -d)
  if fetch "https://github.com/ryanoasis/nerd-fonts/releases/latest/download/JetBrainsMono.tar.xz" "$tmp/f.txz" \
      && tar -tJf "$tmp/f.txz" >/dev/null 2>&1; then
    mkdir -p "$FONT_DIR"
    if ! tar -xJf "$tmp/f.txz" -C "$FONT_DIR" 2>/dev/null; then
      python3 -c 'import sys,tarfile; tarfile.open(sys.argv[1]).extractall(sys.argv[2])' "$tmp/f.txz" "$FONT_DIR" 2>/dev/null || { warn "could not unpack the font"; rm -rf "$tmp"; return 1; }
    fi
    find "$FONT_DIR" -type f ! -iname '*.ttf' ! -iname '*.otf' -delete 2>/dev/null || true
    local fonts; fonts=$(find "$FONT_DIR" -type f \( -iname '*.ttf' -o -iname '*.otf' \) -print -quit)
    if [[ -z $fonts ]]; then warn "the downloaded archive contained no usable font files"; rm -rf "$tmp"; return 1; fi
    have fc-cache && fc-cache -f "$FONT_DIR" >/dev/null 2>&1 || true
    rm -rf "$tmp"
    if font_has_v3_glyphs; then
      ok "Nerd Font v3+ installed and current icon glyphs verified in $FONT_DIR"
      info "select 'JetBrainsMono Nerd Font' in your terminal if it is not selected automatically"
      return 0
    fi
    warn "font files were downloaded, but fontconfig cannot find the required v3 icon glyph; refresh the terminal font cache and select JetBrainsMono Nerd Font"
    return 1
  else
    warn "Nerd Font download or archive validation failed; check network access and try again"
    rm -rf "$tmp"
    return 1
  fi
}


# tools every later step relies on (git is needed by the fzf fallback, xz/tar by fonts)
ensure_basics() {
  [[ -n $PM && $NO_PRIV == 0 ]] || return 0
  local t pkg
  for t in curl git tar xz unzip fc-cache; do
    have "$t" && continue
    case $t in
      fc-cache) pkg=fontconfig ;;
      xz) if [[ $PM == apt ]]; then pkg=xz-utils; else pkg=xz; fi ;;
      *) pkg=$t ;;
    esac
    try_pkg "$pkg" || warn "could not install $pkg (some optional features may be skipped)"
  done
  return 0
}

# ---- lib/steps.sh ----
# lib/steps.sh - shell/terminal integration, art wizard, finish message
choose_shells() {
  local login="${SHELL##*/}" s
  TARGETS=()
  case $SHELLS in
    zsh) TARGETS=(zsh) ;; bash) TARGETS=(bash) ;; both) TARGETS=(zsh bash) ;;
    auto)
      for s in zsh bash; do
        have "$s" || continue
        local rc="$HOME/.${s}rc"; [[ $s == zsh ]] && rc="${ZDOTDIR:-$HOME}/.zshrc"
        if [[ $login == "$s" || -f $rc ]]; then TARGETS+=("$s"); fi
      done
      ((${#TARGETS[@]})) || TARGETS=(bash) ;;
  esac
}

integrate_shells() {
  local s rc
  for s in "${TARGETS[@]}"; do
    rc="$HOME/.${s}rc"; [[ $s == zsh ]] && rc="${ZDOTDIR:-$HOME}/.zshrc"
    local res; res=$(rc_patch "$rc" install "$CONF_DIR/init.$s" "$KEEP_FETCH")
    ok "$s: $rc ($res; backup kept when changed)"
  done
  if ((! KEEP_FETCH)); then
    local f
    for f in "${ZDOTDIR:-$HOME}/.zprofile" "${ZDOTDIR:-$HOME}/.zshenv" "$HOME/.bash_profile" "$HOME/.profile"; do
      if [[ -f $f ]]; then rc_patch "$f" clean "" 0 >/dev/null; fi
    done
  fi
  return 0
}

integrate_terminals() {
  ((DO_TERM)) || return 0
  local did=0
  if have ghostty || [[ -d ${XDG_CONFIG_HOME:-$HOME/.config}/ghostty ]]; then
    local d="${XDG_CONFIG_HOME:-$HOME/.config}/ghostty" f
    mkdir -p "$d"; f="$d/config"; touch "$f"
    if ! grep -q 'termfx/ghostty.conf' "$f"; then
      cp -n "$f" "$f.termfx.bak" 2>/dev/null || true
      printf '\n# termfx\nconfig-file = ?%s/ghostty.conf\n' "$CONF_DIR" >> "$f"
    fi
    ok "Ghostty: loads $CONF_DIR/ghostty.conf (your own settings stay untouched)"; did=1
  fi
  if have kitty || [[ -d ${XDG_CONFIG_HOME:-$HOME/.config}/kitty ]]; then
    local d="${XDG_CONFIG_HOME:-$HOME/.config}/kitty" f
    mkdir -p "$d"; f="$d/kitty.conf"; touch "$f"
    if ! grep -q 'termfx/kitty.conf' "$f"; then
      cp -n "$f" "$f.termfx.bak" 2>/dev/null || true
      printf '\n# termfx\ninclude %s/kitty.conf\n' "$CONF_DIR" >> "$f"
    fi
    ok "kitty: includes $CONF_DIR/kitty.conf"; did=1
  fi
  ((did)) || info "no Ghostty/kitty found - for other terminals just pick the 'JetBrainsMono Nerd Font' font (theme snippets are in $CONF_DIR)"
}

ask() { # prompt default
  local a=""
  if ((ASSUME_YES)) || ! have_tty; then printf '%s' "$2"; return; fi
  read -r -p "$1" a </dev/tty || a=""
  printf '%s' "${a:-$2}"
}

art_wizard() {
  local termfx="$BIN_DIR/termfx"
  # explicit flags first
  if [[ -n $ART_SRC ]]; then
    [[ -f $ART_SRC ]] || die "art file not found: $ART_SRC"
    "$termfx" art add "${ART_NAME:-custom}" "$ART_SRC" -u || warn "could not import art"; return 0
  fi
  if [[ -n $ART_URL ]]; then "$termfx" art add "${ART_NAME:-custom}" "$ART_URL" -u || warn "could not download art"; return 0; fi
  if ((PASTE)); then
    have_tty || die "--paste needs a terminal"
    printf '%sPaste your ASCII art, then press Ctrl-D on an empty line:%s\n' "$CB" "$C0"
    "$termfx" art add "${ART_NAME:-custom}" - -u </dev/tty || true; return 0
  fi
  ((ASSUME_YES)) && return 0
  have_tty || return 0

  local names=() n i=0
  while IFS= read -r n; do names+=("$n"); done < <("$BIN_DIR/termfx-engine" list art)
  printf '\n  %sChoose your header art:%s\n' "$CB" "$C0"
  for n in "${names[@]}"; do i=$((i+1)); printf '   %s%3d)%s %s\n' "$CM" "$i" "$C0" "$n"; done
  printf '   %s  p)%s paste my own ASCII art now\n   %s  f)%s load from a file / URL\n   %s  d)%s my distro logo (needs fastfetch)\n   %s  r)%s random each time\n' "$CM" "$C0" "$CM" "$C0" "$CM" "$C0" "$CM" "$C0"
  local c; c=$(ask "  choice [1]: " "1")
  case $c in
    p|P) printf '  %sPaste now, finish with Ctrl-D on an empty line:%s\n' "$CD" "$C0"
         "$termfx" art add custom - -u </dev/tty || true ;;
    f|F) local s; s=$(ask "  path or URL: " "")
         if [[ -z $s ]]; then warn "no path given - keeping default art"
         else "$termfx" art add custom "$s" -u || warn "import failed"; fi ;;
    d|D) "$termfx" art distro || warn "could not get distro logo (is fastfetch installed?)" ;;
    r|R) "$termfx" set art random >/dev/null; ok "art = random (picks a new one each terminal)" ;;
    ''|*[!0-9]*)
      if [[ -n $c && $c != 1 ]]; then warn "invalid choice '$c' - using #1 (${names[0]:-girl})"; fi
      [[ ${#names[@]} -ge 1 ]] && { "$termfx" set art "${names[0]}" >/dev/null; ok "art = ${names[0]}"; } ;;
    *) if ((c >= 1 && c <= ${#names[@]})); then
         "$termfx" set art "${names[c-1]}" >/dev/null; ok "art = ${names[c-1]}"
       else
         warn "choice out of range - using #1 (${names[0]:-girl})"
         [[ ${#names[@]} -ge 1 ]] && { "$termfx" set art "${names[0]}" >/dev/null; ok "art = ${names[0]}"; }
       fi ;;
  esac

  if [[ -z $EFFECT ]]; then
    local fx=() descs=() fxpal=() line
    while IFS=$'\t' read -r n line c; do
      fx+=("$n"); descs+=("$line"); fxpal+=("$c")
    done < <("$BIN_DIR/termfx-engine" list effect-menu)
    ((${#fx[@]})) || fx=(aurora wave rainbow plasma fire matrix pulse static)
    printf '\n  %s%s effects%s - pick a number or a name (Enter = aurora):\n' "$CB" "${#fx[@]}" "$C0"
    local i ecols; ecols=$(_tw)
    for i in "${!fx[@]}"; do
      if ((ecols >= 80)); then
        printf '   %s%3d)%s %-14s %s%-36s palette: %s%s\n' "$CM" "$((i+1))" "$C0" "${fx[i]}" "$CD" "${descs[i]:-}" "${fxpal[i]:-auto}" "$C0"
      else       # narrow terminal: keep each entry on one line so nothing wraps into the next row
        printf '   %s%3d)%s %-14s %s%.*s%s\n' "$CM" "$((i+1))" "$C0" "${fx[i]}" "$CD" "$((ecols > 26 ? ecols - 26 : 0))" "${descs[i]:-}" "$C0"
      fi
    done
    c=$(ask "  effect [1=aurora]: " "1")
    if [[ $c =~ ^[0-9]+$ ]] && ((c >= 1 && c <= ${#fx[@]})); then
      EFFECT=${fx[c-1]}; ok "effect = $EFFECT"
    elif [[ -n $c && $c != 1 ]]; then
      local found=0
      for n in "${fx[@]}"; do [[ $n == "$c" ]] && { EFFECT=$c; found=1; break; }; done
      if ((found)); then ok "effect = $EFFECT"
      else warn "unknown effect '$c' - using aurora"; EFFECT=aurora; fi
    else
      EFFECT=aurora
    fi
  fi

  # palette selection
  if [[ -z $PALETTE ]]; then
    local pals=() pstops=() phex=() n2
    while IFS= read -r n; do
      pals+=("${n%% *}")
      n2=${n#* }; pstops+=("${n2%% *}"); phex+=("${n2#* }")
    done < <("$BIN_DIR/termfx-engine" list palette-menu)
    if ((${#pals[@]})); then
      local pcols=${COLUMNS:-0}
      ((pcols > 0)) || pcols=$(tput cols 2>/dev/null || echo 80)
      printf '\n  %s%s palettes%s - pick a number or a name (Enter = auto = best for the effect):\n' "$CB" "${#pals[@]}" "$C0"
      local p i h r g bl sw hx
      for i in "${!pals[@]}"; do
        sw=""; hx=""
        for h in ${phex[i]}; do
          hx+="#$h "
          if [[ -n $C0 ]]; then
            r=$((16#${h:0:2})); g=$((16#${h:2:2})); bl=$((16#${h:4:2}))
            sw+=$(printf '\033[48;2;%d;%d;%dm  ' "$r" "$g" "$bl")      # colour swatch; the hex text keeps the normal colour so it stays readable on any background
          fi
        done
        [[ -n $sw ]] && sw+=$C0
        hx=${hx% }
        if ((pcols >= 112)); then      # wide terminal: everything on one line
          printf '   %s%3d)%s %-14s %s%d stops%s  %s%*s %s%s%s\n' "$CM" "$((i+1))" "$C0" "${pals[i]}" "$CD" "${pstops[i]}" "$C0" "$sw" "$(( (8 - ${pstops[i]}) * 2 ))" "" "$CD" "$hx" "$C0"
        else                           # narrow terminal: hex values on their own line so nothing wraps
          printf '   %s%3d)%s %-14s %s%d stops%s  %s\n' "$CM" "$((i+1))" "$C0" "${pals[i]}" "$CD" "${pstops[i]}" "$C0" "$sw"
          printf '%s\n' "$hx" | fold -s -w "$((pcols > 16 ? pcols - 8 : 8))" | while IFS= read -r hl; do printf '        %s%s%s\n' "$CD" "${hl%"${hl##*[![:space:]]}"}" "$C0"; done
        fi
      done
      printf '   %s  a)%s %-14s %sbest palette for the chosen effect (recommended)%s\n' "$CM" "$C0" "auto" "$CD" "$C0"
      c=$(ask "  palette (number, name, or custom #hex,#hex,...) [a=auto]: " "a")
      if [[ $c == a || $c == A || -z $c ]]; then
        PALETTE=auto
      elif [[ $c =~ ^[0-9]+$ ]] && ((c >= 1 && c <= ${#pals[@]})); then
        PALETTE=${pals[c-1]}
      elif [[ $c =~ ^#?[0-9a-fA-F]{6}(,#?[0-9a-fA-F]{6})+$ ]]; then
        PALETTE=$c                                  # custom colours, e.g. #ff0080,#00e5ff,#7a00ff
      else
        local pfound=0
        for p in "${pals[@]}"; do [[ $p == "$c" ]] && { PALETTE=$c; pfound=1; break; }; done
        if ((!pfound)); then warn "unknown palette '$c' - using auto"; PALETTE=auto; fi
      fi
      ok "palette = $PALETTE"
    fi
  fi

  # fastfetch panel preset
  if [[ -z ${FETCH_PRESET:-} ]]; then
    local fpresets=() fpdescs=()
    while IFS= read -r line; do
      fpresets+=("${line%% *}")
      fpdescs+=("$(printf '%s' "${line#* }" | sed 's/^[[:space:]]*//')")
    done < <(CONF_DIR="$CONF_DIR" python3 "$BIN_DIR/termfx-themes" --list fetch 2>/dev/null)
    if ((${#fpresets[@]})); then
      printf '\n  %s%s Fastfetch panel presets%s (Enter = classic):\n' "$CB" "${#fpresets[@]}" "$C0"
      local fi2
      for fi2 in "${!fpresets[@]}"; do
        printf '   %s%3d)%s %-14s %s%s%s\n' "$CM" "$((fi2+1))" "$C0" "${fpresets[$fi2]}" "$CD" "${fpdescs[$fi2]}" "$C0"
      done
      c=$(ask "  fetch preset [1=classic]: " "1")
      if [[ $c =~ ^[0-9]+$ ]] && ((c >= 1 && c <= ${#fpresets[@]})); then
        FETCH_PRESET=${fpresets[c-1]}
      elif [[ -n $c && $c != 1 ]]; then
        local ffound=0
        for n in "${fpresets[@]}"; do [[ $n == "$c" ]] && { FETCH_PRESET=$c; ffound=1; break; }; done
        ((ffound)) || FETCH_PRESET=classic
      else
        FETCH_PRESET=classic
      fi
      ok "fetch preset = $FETCH_PRESET"
    fi
  fi
}

starship_theme_wizard() {
  local current choice
  if [[ -n ${STARSHIP_THEME:-} ]]; then
    "$BIN_DIR/termfx" starship theme "$STARSHIP_THEME"
    return
  fi
  ((ASSUME_YES)) && return 0
  have_tty || return 0
  current=$(awk -F= '/^[[:space:]]*starship_theme[[:space:]]*=/ {split($2, v, "#"); gsub(/[[:space:]]/, "", v[1]); print v[1]}' "$CONF_DIR/config" 2>/dev/null | tail -n1)
  current=${current:-terminal-match}
  local snames=() sdescs=() n d i
  while IFS= read -r n; do
    snames+=("${n%% *}"); d=${n#* }; sdescs+=("${d#"${d%%[![:space:]]*}"}")
  done < <(CONF_DIR="$CONF_DIR" python3 "$BIN_DIR/termfx-themes" --list starship)
  printf '\n  %s%s Starship prompt themes%s - pick a number or a name:\n' "$CB" "${#snames[@]}" "$C0"
  for i in "${!snames[@]}"; do
    printf '   %s%3d)%s %-20s %s%s%s%s\n' "$CM" "$((i+1))" "$C0" "${snames[i]}" "$CD" "${sdescs[i]}" "$C0" "$([[ ${snames[i]} == "$current" ]] && printf ' (current)')"
  done
  choice=$(ask "  theme [Enter keeps $current]: " "")
  [[ -z $choice ]] && { info "keeping Starship theme: $current"; return 0; }
  if [[ $choice =~ ^[0-9]+$ ]]; then
    if ((choice >= 1 && choice <= ${#snames[@]})); then choice=${snames[choice-1]}
    else warn "choice out of range - keeping $current"; return 0; fi
  fi
  "$BIN_DIR/termfx" starship theme "$choice"
}

_tool_line() { # cmd label
  if have "$1"; then printf '    %s✔%s %-12s ready\n' "$CG" "$C0" "$2"
  else printf '    %s·%s %-12s not installed (optional)\n' "$CD" "$C0" "$2"; fi
}

# one aligned line of the summary: command (coloured) + padded description column
_cmd() { printf '    %s%-40s%s %s\n' "$CC" "$1" "$C0" "$2"; }

finish_message() {
  cat <<EOF

${CG}${CB}  ✔ termfx $VERSION installed${C0}

  ${CB}Open a new terminal${C0} (or run ${CC}exec \$SHELL${C0}) to see the animated header.
  It needs a window of about ${CB}80×24${C0} or more; below that the header hides itself.
  If p10k or oh-my-posh is still active (--keep-old), keep only one prompt tool.

  ${CB}What's ready${C0}
EOF
  _tool_line python3   python3
  _tool_line starship  starship
  _tool_line fastfetch fastfetch
  _tool_line eza       eza
  { have bat || have batcat; } && printf '    %s✔%s %-12s ready\n' "$CG" "$C0" "bat" \
    || printf '    %s·%s %-12s not installed (optional)\n' "$CD" "$C0" "bat"
  _tool_line fzf       fzf
  local n_pal; n_pal=$("$BIN_DIR/termfx-engine" list palettes 2>/dev/null | grep -c .)
  cat <<EOF

  ${CB}Features & commands${C0}
EOF
  _cmd "termfx effect list"                 "list all animated effects"
  _cmd "termfx effect next"                 "cycle through effects live"
  _cmd "termfx effect info NAME"            "details + recommended palette"
  _cmd "termfx palette list"                "${n_pal:-?} colour palettes"
  _cmd "termfx palette show NAME"           "preview colours with gradient"
  _cmd "termfx palette next"                "cycle through palettes"
  _cmd "termfx preview effect=fire"         "full-screen preview (any key exits)"
  _cmd "termfx theme list"                  "change shell/prompt colours"
  _cmd "termfx starship theme list"         "browse named prompt themes"
  _cmd "termfx starship theme cloud-ops"    "apply a Starship theme"
  _cmd "termfx art add mine"                "paste your own ASCII art"
  _cmd "termfx info items"                  "manage the system info panel"
  _cmd "termfx info custom 'CMD'"           "custom info panel command"
  _cmd "termfx randomize"                   "instant random look"
  _cmd "termfx profile save work"           "save/load config profiles"
  _cmd "termfx --help"                      "full feature list"
  cat <<EOF

  ${CB}All effects${C0} (descriptions and recommended palettes):
EOF
  "$BIN_DIR/termfx" effect list
  cat <<EOF

  ${CB}All palettes${C0} (colour stop count and hex values):
EOF
  "$BIN_DIR/termfx-engine" list palette-details
  local n_st n_ff
  n_st=$(python3 "$BIN_DIR/termfx-themes" --list starship 2>/dev/null | grep -c .)
  n_ff=$(python3 "$BIN_DIR/termfx-themes" --list fetch 2>/dev/null | grep -c .)
  cat <<EOF

  ${CB}Quick tips${C0}
EOF
  _cmd "termfx starship theme developer-forge" "one of ${n_st:-?} Starship themes"
  _cmd "termfx starship set right_prompt true" "customize Starship controls"
  _cmd "termfx fastfetch gamer"                "one of ${n_ff:-?} info panel presets"
  _cmd "termfx glitch on"                      "random glitch distortions"
  _cmd "termfx info-colors neon"               "colour the info panel"
  _cmd "termfx set sparkle true"               "sparkle effect on the header"
  _cmd "termfx set vignette true"              "cinematic edge darkening"
  _cmd "termfx rotate on 60"                   "auto-rotate effects every 60s"
  _cmd "termfx align center"                   "centre the header"
  cat <<EOF

  Restore old setup:  ${CC}termfx restore${C0}
  Uninstall:          ${CC}termfx uninstall${C0}
  Something wrong?:   ${CC}termfx doctor${C0}
EOF
  case ":$PATH:" in *":$BIN_DIR:"*) ;; *) warn "$BIN_DIR is not in your PATH yet - it will be after you open a new terminal." ;; esac
}

# ---- lib/reset.sh ----
# lib/reset.sh - back up + reset old terminal customizations, and restore them
BACKUP_ROOT="$HOME/.termfx-backup"

# Everything that can fight with termfx. Only touches $HOME (and $ZDOTDIR), never /etc.
RESET_PATHS=(
  .bashrc .bash_profile .bash_login .profile .bash_aliases .bash_logout
  .zshrc .zprofile .zshenv .zlogin .zlogout .zsh_aliases '.zcompdump*'
  .p10k.zsh .oh-my-zsh .zinit .zplug .antigen .zsh .zim .zimrc .sheldon
  .config/starship.toml .config/oh-my-posh .config/ohmyposh
  .config/fastfetch .config/neofetch
  .config/ghostty .config/kitty .config/alacritty .config/wezterm
  .wezterm.lua .alacritty.yml .alacritty.toml
)

# zsh files that may live under $ZDOTDIR instead of $HOME
ZDOT_NAMES=(.zshrc .zprofile .zshenv .zlogin .zlogout .zsh_aliases .p10k.zsh)

write_clean_defaults() {
  local f
  for f in .bashrc .profile .bash_logout; do
    if [[ -r /etc/skel/$f ]]; then
      cp -- "/etc/skel/$f" "$HOME/$f"
    elif [[ $f == .bashrc ]]; then
      printf '%s\n' '# default ~/.bashrc' '[[ $- != *i* ]] && return' \
        "alias ls='ls --color=auto'" "alias ll='ls -lh'" "PS1='[\\u@\\h \\W]\\$ '" > "$HOME/$f"
    elif [[ $f == .profile ]]; then
      printf '%s\n' '# default ~/.profile' \
        '[ -n "$BASH_VERSION" ] && [ -f "$HOME/.bashrc" ] && . "$HOME/.bashrc"' > "$HOME/$f"
    fi
  done

  # only recreate a zshrc when the user actually uses zsh - otherwise bash-only
  # users with zsh installed would get both shells patched by --shell auto
  local write_zsh=0 zrc="${ZDOTDIR:-$HOME}/.zshrc"
  case ${SHELL##*/} in zsh) write_zsh=1 ;; esac
  case ${SHELLS:-auto} in zsh|both) write_zsh=1 ;; esac
  if [[ -f $BACKUP_ROOT/latest/MANIFEST ]] && grep -qE '(^|/)\.zshrc$' "$BACKUP_ROOT/latest/MANIFEST" 2>/dev/null; then
    write_zsh=1
  fi
  if ((write_zsh)) && have zsh; then
    mkdir -p "$(dirname "$zrc")"
    printf '%s\n' '# default ~/.zshrc' \
      'HISTFILE=~/.zsh_history; HISTSIZE=10000; SAVEHIST=10000' \
      'setopt autocd histignoredups' \
      'autoload -Uz compinit && compinit' \
      "alias ls='ls --color=auto'" > "$zrc"
  fi
}

termfx_already_installed() {
  local f
  for f in "${ZDOTDIR:-$HOME}/.zshrc" "$HOME/.bashrc"; do
    [[ -f $f ]] && grep -qF "$MARK_BEGIN" "$f" && return 0
  done
  return 1
}

# collect paths under HOME matching RESET_PATHS, plus ZDOTDIR files outside HOME
_collect_reset_list() {
  local p f zd
  list=()
  shopt -s nullglob
  for p in "${RESET_PATHS[@]}"; do
    for f in "$HOME"/$p; do
      if [[ -e $f || -L $f ]]; then list+=("${f#"$HOME"/}"); fi
    done
  done
  shopt -u nullglob
  zd="${ZDOTDIR:-}"
  if [[ -n $zd && $zd != "$HOME" ]]; then
    for p in "${ZDOT_NAMES[@]}"; do
      f="$zd/$p"
      [[ -e $f || -L $f ]] || continue
      case $f in
        "$HOME"/*) list+=("${f#"$HOME"/}") ;;
        *)
          # store outside-HOME ZDOTDIR files under a dedicated backup folder
          list+=("__zdotdir__/$p")
          ;;
      esac
    done
  fi
}

reset_to_defaults() {
  local ts dest rel f p a gt=0
  local list=()
  # re-running the installer must never overwrite the backup of the user's ORIGINAL setup
  if termfx_already_installed && [[ ${RESET:-1} != 2 ]]; then
    info "termfx is already set up here - keeping your first backup untouched (use --reset to force)"
    return 0
  fi
  ts=$(date +%Y%m%d-%H%M%S); dest="$BACKUP_ROOT/$ts"
  _collect_reset_list

  # GNOME Terminal settings are only touched when there actually are some (and the user is told)
  if have dconf && [[ -n $(dconf dump /org/gnome/terminal/ 2>/dev/null) ]]; then gt=1; fi
  if ((${#list[@]} == 0 && gt == 0)); then
    info "nothing to reset - your terminal is already clean"; return 0
  fi
  info "these old customizations will be MOVED to a backup (nothing is deleted):"
  if ((${#list[@]})); then
    for rel in "${list[@]}"; do
      if [[ $rel == __zdotdir__/* ]]; then
        printf '     %s$ZDOTDIR/%s%s\n' "$CD" "${rel#__zdotdir__/}" "$C0"
      else
        printf '     %s~/%s%s\n' "$CD" "$rel" "$C0"
      fi
    done
  fi
  if ((gt)); then printf '     %sGNOME Terminal settings (profiles, colours, fonts)%s\n' "$CD" "$C0"; fi
  info "backup folder: $dest"
  a=$(ask "  Continue and reset to defaults? [Y/n]: " "y")
  [[ -z $a || $a == [Yy]* ]] || { warn "reset skipped - termfx may clash with your old setup"; return 0; }

  mkdir -p "$dest"; : > "$dest/MANIFEST"
  if [[ -n ${ZDOTDIR:-} && $ZDOTDIR != "$HOME" ]]; then
    printf '%s\n' "$ZDOTDIR" > "$dest/ZDOTDIR"
  fi
  for rel in ${list[@]+"${list[@]}"}; do
    if [[ $rel == __zdotdir__/* ]]; then
      mkdir -p "$dest/__zdotdir__"
      mv -- "${ZDOTDIR}/${rel#__zdotdir__/}" "$dest/$rel" && printf '%s\n' "$rel" >> "$dest/MANIFEST"
    else
      mkdir -p "$dest/$(dirname "$rel")"
      mv -- "$HOME/$rel" "$dest/$rel" && printf '%s\n' "$rel" >> "$dest/MANIFEST"
    fi
  done
  if ((gt)); then
    dconf dump /org/gnome/terminal/ > "$dest/gnome-terminal.dconf" 2>/dev/null || true
    dconf reset -f /org/gnome/terminal/ 2>/dev/null || true
  fi
  ln -sfn "$dest" "$BACKUP_ROOT/latest"
  [[ -e $BACKUP_ROOT/original ]] || ln -sfn "$dest" "$BACKUP_ROOT/original"
  write_clean_defaults
  ok "reset done. Restore anytime with:  termfx restore"
}

restore_backup() {
  local src=${1:-} rel f zd
  if [[ -z $src ]]; then if [[ -d $BACKUP_ROOT/original ]]; then src=$BACKUP_ROOT/original; else src=$BACKUP_ROOT/latest; fi; fi
  [[ -d $src && -f $src/MANIFEST ]] || { err "no backup found in $BACKUP_ROOT"; return 1; }
  src=$(readlink -f "$src")
  for f in "${ZDOTDIR:-$HOME}/.zshrc" "$HOME/.bashrc"; do
    [[ -f $f ]] && rc_patch "$f" uninstall "" 0 >/dev/null
  done
  zd="${ZDOTDIR:-}"
  [[ -f $src/ZDOTDIR ]] && zd=$(cat "$src/ZDOTDIR")
  while IFS= read -r rel; do
    [[ -n $rel ]] || continue
    if [[ $rel == __zdotdir__/* ]]; then
      [[ -n $zd ]] || continue
      rm -rf -- "${zd:?}/${rel#__zdotdir__/}"
      mkdir -p "$zd"
      cp -a -- "$src/$rel" "$zd/${rel#__zdotdir__/}"
    else
      rm -rf -- "${HOME:?}/$rel"
      mkdir -p "$(dirname "$HOME/$rel")"
      cp -a -- "$src/$rel" "$HOME/$rel"
    fi
  done < "$src/MANIFEST"
  if [[ -f $src/gnome-terminal.dconf ]] && have dconf; then dconf load /org/gnome/terminal/ < "$src/gnome-terminal.dconf"; fi
  ok "restored your old setup from $src - open a new terminal"
  info "termfx binaries may still be in ~/.local/bin - run  termfx uninstall  if you want those gone too"
}

# ---- lib/font.sh ----
# lib/font.sh - make the Nerd Font actually active (otherwise beginners see boxes)
activate_font() {
  local name="JetBrainsMono Nerd Font" did=0 u gpath d
  # never point the terminal at a font that is not installed (e.g. --no-font / --no-packages):
  # the user would get a fallback font and broken icons
  if ! font_has_v3_glyphs; then
    warn "$name v3+ with current icon glyphs is not installed - leaving the terminal font alone"
    info "install the latest Nerd Font, pick it in your terminal, then run: termfx set icons true"
    info "until then a plain prompt (no icons, still with folder + clock) is used"
    "$BIN_DIR/termfx" set icons false >/dev/null 2>&1 || true
    return 0
  fi
  if have gsettings && have gnome-terminal; then
    u=$(gsettings get org.gnome.Terminal.ProfilesList default 2>/dev/null | tr -d "'") || u=""
    [[ -n $u ]] || u="b1dcc9dd-5262-4d8d-a863-c897e6d979b9"
    gpath="org.gnome.Terminal.Legacy.Profile:/org/gnome/terminal/legacy/profiles:/:$u/"
    if gsettings set "$gpath" use-system-font false 2>/dev/null && gsettings set "$gpath" font "$name 12" 2>/dev/null; then did=1; fi
  fi
  if have konsole; then
    d="$HOME/.local/share/konsole"; mkdir -p "$d"
    printf '[Appearance]\nFont=%s,12,-1,5,50,0,0,0,0,0\n\n[General]\nName=termfx\nParent=FALLBACK/\n' "$name" > "$d/termfx.profile"
    if have kwriteconfig6; then kwriteconfig6 --file konsolerc --group "Desktop Entry" --key DefaultProfile termfx.profile || true
    elif have kwriteconfig5; then kwriteconfig5 --file konsolerc --group "Desktop Entry" --key DefaultProfile termfx.profile || true; fi
    did=1
  fi
  if ((did)); then
    ok "terminal font set to $name"
  else
    warn "could not set the font automatically for your terminal"
    info "open your terminal's Preferences and choose '$name', then run: termfx set icons true"
    info "until then a plain prompt (no icons, still with folder + clock) is used"
    "$BIN_DIR/termfx" set icons false >/dev/null 2>&1 || true
  fi
}


# ------------------------------------------------------------------ arguments
CMD=install; RESET=1; ASSUME_YES=0; DO_PKGS=1; DO_FONT=auto; DO_TERM=1; KEEP_FETCH=0
SHELLS=auto; ART_SRC=""; ART_URL=""; ART_NAME=""; PASTE=0; EFFECT=""; PALETTE=""; FETCH_PRESET=""; STARSHIP_THEME=""
FORCE=0; PURGE=0; RESTORE_SRC=""

while (($#)); do
  case $1 in
    install|uninstall|restore|doctor) CMD=$1 ;;
    -y|--yes)        ASSUME_YES=1 ;;
    --art)           ART_SRC=${2:?--art needs a file}; shift ;;
    --art=*)         ART_SRC=${1#*=} ;;
    --art-url)       ART_URL=${2:?--art-url needs a URL}; shift ;;
    --art-url=*)     ART_URL=${1#*=} ;;
    --art-name)      ART_NAME=${2:?}; shift ;;
    --art-name=*)    ART_NAME=${1#*=} ;;
    --paste)         PASTE=1 ;;
    --effect)        EFFECT=${2:?}; shift ;;
    --effect=*)      EFFECT=${1#*=} ;;
    --palette)       PALETTE=${2:?}; shift ;;
    --palette=*)     PALETTE=${1#*=} ;;
    --fetch-preset)  FETCH_PRESET=${2:?}; shift ;;
    --fetch-preset=*) FETCH_PRESET=${1#*=} ;;
    --starship-theme) STARSHIP_THEME=${2:?--starship-theme needs a name}; shift ;;
    --starship-theme=*) STARSHIP_THEME=${1#*=} ;;
    --shell)         SHELLS=${2:?}; shift ;;
    --shell=*)       SHELLS=${1#*=} ;;
    --no-packages)   DO_PKGS=0 ;;
    --no-font)       DO_FONT=0 ;;
    --font)          DO_FONT=1 ;;
    --no-terminal)   DO_TERM=0 ;;
    --keep-fetch)    KEEP_FETCH=1 ;;
    --keep-old)      RESET=0 ;;
    --reset)         RESET=2 ;;
    --force)         FORCE=1 ;;
    --purge)         PURGE=1 ;;
    -h|--help)       usage; exit 0 ;;
    *) if [[ $CMD == restore && $1 != -* && -z $RESTORE_SRC ]]; then RESTORE_SRC=$1   # termfx restore [DIR]
       else die "unknown option: $1 (try --help)"; fi ;;
  esac
  shift
done
case $SHELLS in auto|zsh|bash|both) ;; *) die "--shell must be auto|zsh|bash|both" ;; esac

# ---------------------------------------------------------------- file writers
ART_NAMES="girl arch tux blocks spinner"
ENGINE_MODULES=(src/termfx_engine/__init__.py src/termfx_engine/__main__.py
                src/termfx_engine/_shared.py src/termfx_engine/_system.py
                src/termfx_engine/_color.py src/termfx_engine/_art.py
                src/termfx_engine/_info.py src/termfx_engine/_layout.py
                src/termfx_engine/_effects.py src/termfx_engine/_render.py
                src/termfx_engine/_menu.py src/termfx_engine/_commands.py)
CLI_MODULES=(src/termfx.d/settings.sh src/termfx.d/art.sh src/termfx.d/status.sh)
write_engine() {
  put src/termfx-engine "$BIN_DIR/termfx-engine" 755
  if [[ ${TERMFX_DIST:-0} == 1 ]]; then
    emit engine_bundle | python3 -c 'import io,sys,zipfile; zipfile.ZipFile(io.BytesIO(sys.stdin.buffer.read())).extractall(sys.argv[1])' "$BIN_DIR/termfx_engine"
  else
    local f; for f in "${ENGINE_MODULES[@]}"; do put "$f" "$BIN_DIR/termfx_engine/${f##*/}"; done
  fi
}
write_cli() {
  put src/termfx "$BIN_DIR/termfx" 755
  local f; for f in "${CLI_MODULES[@]}"; do put "$f" "$BIN_DIR/termfx.d/${f##*/}"; done
  put gen/themes.py "$BIN_DIR/termfx-themes" 755
}
write_init_zsh()  { put src/init.zsh  "$CONF_DIR/init.zsh"; }
write_init_bash() { put src/init.bash "$CONF_DIR/init.bash"; }
write_art() {
  local n f; mkdir -p "$ART_DIR"
  for n in $ART_NAMES; do
    f="$ART_DIR/$n.txt"
    if [[ ! -f $f || $FORCE == 1 ]]; then put "src/art/$n.txt" "$f"; fi
  done
}
write_default_config() {
  [[ -f $CONF_DIR/config && $FORCE != 1 ]] && return 0
  put src/config.default "$CONF_DIR/config"
}
write_generated_configs() {
  have python3 || { warn "python3 missing - skipping starship/fastfetch themes"; return 0; }
  emit gen/themes.py | CONF_DIR="$CONF_DIR" python3 -
}
rc_patch() { # file mode(install|clean|uninstall) init keep_fetch
  emit lib/rcpatch.py | python3 - "$1" "$2" "${3:-}" "${4:-0}"
}

# keep a copy of the installer so  termfx uninstall / termfx restore  work later
keep_installer_copy() {
  mkdir -p "$DATA_DIR"
  if [[ ${TERMFX_DIST:-0} == 1 ]]; then
    if [[ -r $SELF && -f $SELF ]]; then install -m755 "$SELF" "$DATA_DIR/install.sh" 2>/dev/null || true; fi
  else
    rm -rf "$DATA_DIR/tree"; mkdir -p "$DATA_DIR/tree"
    cp -r "$ROOT/install.sh" "$ROOT/lib" "$ROOT/src" "$ROOT/gen" "$DATA_DIR/tree/"
    printf '#!/bin/sh\nexec sh "%s/tree/install.sh" "$@"\n' "$DATA_DIR" > "$DATA_DIR/install.sh"
    chmod 755 "$DATA_DIR/install.sh"
  fi
}

do_install() {
  banner
  [[ $(id -u) -eq 0 && -z ${SUDO_USER:-} && ${TERMFX_ALLOW_ROOT:-0} != 1 ]] && warn "running as root: everything will be installed for root's HOME ($HOME)"
  have python3 || [[ $DO_PKGS == 1 ]] || die "python3 is required (re-run without --no-packages)"

  step "Installing packages (fastfetch, starship, eza, bat, fzf)"
  if ((DO_PKGS)); then install_packages; ensure_basics; else info "skipped (--no-packages)"; detect_system; mkdir -p "$BIN_DIR"; have python3 || die "python3 is required"; fi

  step "Nerd Font"
  if [[ $DO_FONT == 0 ]]; then info "skipped (--no-font)"
  elif [[ $DO_FONT == 1 ]]; then install_font || warn "font setup failed; continuing with icons disabled until a Nerd Font v3+ is selected"
  elif ((DO_PKGS)); then install_font || warn "font setup failed; continuing with icons disabled until a Nerd Font v3+ is selected"
  else info "skipped (--no-packages; pass --font to force)"; fi

  step "Resetting old terminal customizations"
  if ((RESET)); then reset_to_defaults; else info "skipped (--keep-old)"; fi

  step "Writing termfx files"
  mkdir -p "$BIN_DIR" "$CONF_DIR" "$ART_DIR" "$DATA_DIR" "$CACHE_DIR"
  write_engine; write_cli; ok "engine + CLI -> $BIN_DIR"
  write_init_zsh; write_init_bash; ok "shell integrations (zsh, bash)"
  write_art; ok "built-in art -> $ART_DIR"
  write_default_config; write_generated_configs; ok "config, starship + fastfetch themes -> $CONF_DIR"
  keep_installer_copy
  python3 -m compileall -q "$BIN_DIR/termfx_engine" 2>/dev/null && ok "engine compiles" || die "engine failed to compile"
  export PATH="$BIN_DIR:$PATH"

  step "Your ASCII art"
  art_wizard
  starship_theme_wizard
  [[ -n $EFFECT ]] && "$BIN_DIR/termfx" effect "$EFFECT" >/dev/null || true
  [[ -n $PALETTE ]] && "$BIN_DIR/termfx" palette "$PALETTE" >/dev/null || true
  [[ -n $FETCH_PRESET ]] && "$BIN_DIR/termfx" fastfetch "$FETCH_PRESET" >/dev/null || true

  step "Terminal emulator look"
  integrate_terminals

  step "Hooking into your shell(s)"
  choose_shells
  integrate_shells

  step "Pre-computing art cache"
  if [[ -t 1 ]]; then "$BIN_DIR/termfx-engine" prepare 2>/dev/null && ok "cached (large art is scaled once, then loads instantly)" || true
  else info "will be cached on first start"; fi

  activate_font

  step "Done"
  finish_message
}

do_uninstall() {
  banner
  STEP_T=4
  step "Removing shell integration"
  local f res
  for f in "${ZDOTDIR:-$HOME}/.zshrc" "$HOME/.bashrc" "${ZDOTDIR:-$HOME}/.zprofile" "${ZDOTDIR:-$HOME}/.zshenv" "$HOME/.bash_profile" "$HOME/.profile"; do
    [[ -f $f ]] || continue
    res=$(rc_patch "$f" uninstall "" 0); [[ $res == patched ]] && ok "cleaned $f"
  done
  step "Removing terminal includes"
  for f in "${XDG_CONFIG_HOME:-$HOME/.config}/ghostty/config" "${XDG_CONFIG_HOME:-$HOME/.config}/kitty/kitty.conf"; do
    [[ -f $f ]] && grep -q termfx "$f" && { sed -i '/^# termfx$/d;/termfx\/\(ghostty\|kitty\)\.conf/d' "$f"; ok "cleaned $f"; }
  done
  step "Removing files"
  pkill -u "$(id -un)" -f 'termfx-engine run' 2>/dev/null || true
  rm -f "$BIN_DIR/termfx" "$BIN_DIR/termfx-engine" "$BIN_DIR/termfx-themes"; rm -rf "$BIN_DIR/termfx.d" "$BIN_DIR/termfx_engine" "$CACHE_DIR"
  rm -f "$CONF_DIR/init.zsh" "$CONF_DIR/init.bash"
  if ((PURGE)); then rm -rf "$CONF_DIR"; ok "config and art deleted"; else info "kept your config/art in $CONF_DIR (use --purge to delete)"; fi
  printf '\x1b[r' 2>/dev/null || true
  if [[ -f $BACKUP_ROOT/original/MANIFEST || -f $BACKUP_ROOT/latest/MANIFEST ]]; then
    local a; a=$(ask "  Restore the terminal setup you had before termfx? [y/N]: " "n")
    [[ $a =~ ^[Yy] ]] && restore_backup
  fi
  rm -rf "$DATA_DIR"
  step "Done"
  ok "termfx removed. Packages (fastfetch, starship, eza...) were left installed. Open a new terminal."
}

case $CMD in
  install)   do_install ;;
  uninstall) do_uninstall ;;
  restore)   restore_backup "${RESTORE_SRC:-}" ;;
  doctor)
    if [[ -x $BIN_DIR/termfx-engine ]]; then exec "$BIN_DIR/termfx-engine" doctor
    else die "termfx is not installed yet. Run the installer first, then: termfx doctor"; fi ;;
esac
